function extraWord(entry,c){const word=entry.replace(/[\[\]]/g,''),mark=entry.indexOf('[');let target=mark>=0?entry.slice(mark+1,entry.indexOf(']')):c.pattern;let pos=mark>=0?mark:word.indexOf(target);if(!target||pos<0){const m=word.match(/(.)\1|[aeiouy]/);target=m?.[0]||word[0];pos=word.indexOf(target)}return {word,target,pos,mask:word.slice(0,pos)+'＿'+word.slice(pos+target.length)}}
