// Test the relevant suffix or grapheme, rather than arbitrary letters in added words.
function targetFor(word,c){const choices=c.name.includes(' · ')?c.name.replace(/[–]/g,'').split(' · '):[c.pattern];const clean=choices.filter(x=>/^[a-z]+$/.test(x));let target=clean.find(t=>word.endsWith(t))||clean.find(t=>word.includes(t))||c.pattern;if(!target||!word.includes(target))return null;return extraWord(word.replace(target,'['+target+']'),c)}
for(const c of chapters){const text=morePatterns[c.name];if(!text||c.level==='Sounds')continue;const additions=text.split(/\s+/).filter(w=>!/^([aeiou])–e$/.test(c.name)||w.endsWith('e')).map(w=>targetFor(w,c)).filter(Boolean);c.words=[...new Map([...c.words,...additions].map(q=>[q.word,q])).values()]}
for(const c of chapters){if(/^([aeiou])–e$/.test(c.name)){const v=c.name[0];c.words=c.words.map(q=>{const pos=q.word.lastIndexOf(v,q.word.length-2);return pos<0?q:{...q,target:v,pos,mask:q.word.slice(0,pos)+'＿'+q.word.slice(pos+1)}})}}
